{
  "name": "@fatihdogmus/opencode-project-tab-groups",
  "version": "1.0.0",
  "description": "OpenCode Desktop plugin that keeps tabs grouped by project, colors and labels each group, and adds a grouped tab switcher",
  "license": "MIT",
  "type": "module",
  "engines": {
    "node": ">=26"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fatihdogmus/opencode-plugins.git",
    "directory": "packages/project-tab-groups"
  },
  "homepage": "https://github.com/fatihdogmus/opencode-plugins/tree/main/packages/project-tab-groups#readme",
  "bugs": {
    "url": "https://github.com/fatihdogmus/opencode-plugins/issues"
  },
  "keywords": [
    "opencode",
    "opencode-desktop",
    "tabs",
    "projects",
    "plugin"
  ],
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "exports": {
    ".": "./src/index.ts",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "src/index.ts",
    "dist"
  ],
  "dependencies": {
    "@opencode/plugin": "2.2.0",
    "effect": "4.0.1"
  },
  "devDependencies": {
    "solid-js": "^1.9.15",
    "typescript": "^7.0.2",
    "vite": "^8.3.5",
    "vite-plugin-solid": "^2.11.0"
  },
  "scripts": {
    "build": "vite build",
    "dev": "vite build --watch",
    "typecheck": "tsc --noEmit",
    "check": "pnpm typecheck && pnpm build"
  }
}

import { Plugin } from "@opencode/plugin"

// The GUI part takes its plugin ID from this server part. Without it the ID would be the npm package name, and renaming
// the package would reset the stored settings (plugin.project-tab-groups.*) and the command IDs users bind keys to.
export default Plugin.define({
  id: "project-tab-groups",
  setup() {},
})
